import fs from'node:fs';import{createRequire}from'node:module';import{ring}from'./ring.mjs';const sharp=createRequire(import.meta.url)(process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES+'/sharp');
const standalone=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024"><rect width="1024" height="1024" fill="#315872"/>${ring({occlude:false})}</svg>`;fs.writeFileSync(new URL('ring-only.svg',import.meta.url),standalone);
const before=await sharp(new URL('../v15/evidence/D-full.jpg',import.meta.url).pathname).raw().toBuffer({resolveWithObject:true}),after=await sharp(new URL('evidence/D-full.jpg',import.meta.url).pathname).raw().toBuffer();const out=Buffer.alloc(after.length);let changed=0;for(let i=0;i<after.length;i+=3){const d=Math.max(...[0,1,2].map(k=>Math.abs(after[i+k]-before.data[i+k])));if(d>12){out[i]=255;out[i+1]=55;out[i+2]=55;changed++;}else{for(let k=0;k<3;k++)out[i+k]=Math.round(before.data[i+k]*.3);}}await sharp(out,{raw:before.info}).png().toFile(new URL('evidence/difference.png',import.meta.url).pathname);fs.writeFileSync(new URL('evidence/difference.json',import.meta.url),JSON.stringify({changedPixelsAbove12:changed,notIdentical:changed>0,comparison:'V15 vs V16 final JPEG; includes numeral moves and JPEG noise; red differences >12 RGB'}));
